"""Fresh replay cases generated by the real store/serve boundary after the fix."""

from __future__ import annotations

import hashlib
from pathlib import Path
from types import SimpleNamespace

import pytest

from amplifier_runtime.client_contract import validate_data_record
from amplifier_runtime.kernel.events import (
    ApprovalRequired,
    ContentBlockEnd,
    OrchestratorComplete,
    StreamBlockDelta,
    ToolPre,
)
from amplifier_runtime.kernel.jsonl import JsonlRecords, ReplayedRuntimeEvent
from amplifier_runtime.kernel.persistence import SessionStore
from amplifier_runtime.kernel.serve import _history_replay_records


def _snapshot(directory: Path) -> dict[str, str]:
    return {
        str(path.relative_to(directory)): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in directory.rglob("*")
        if path.is_file()
    }


@pytest.mark.parametrize("since", [0, 1, 3, 999])
@pytest.mark.parametrize("limit", [0, 1, 2])
def test_fresh_store_replay_preserves_wire_and_ledger(
    tmp_path: Path, since: int, limit: int
) -> None:
    store = SessionStore(base_dir=tmp_path / "sessions")
    events = [
        StreamBlockDelta(event_id="fresh-stream", ts=17.25, text="partial"),
        ContentBlockEnd(event_id="fresh-end", ts=18.5, block={"text": "retained"}),
        ToolPre(event_id="fresh-tool", ts=19.75, tool_name="inspect", tool_call_id="call-C"),
        ApprovalRequired(
            event_id="fresh-approval", ts=20.0, prompt="Fictional task", options=("Allow", "Deny")
        ),
        OrchestratorComplete(event_id="fresh-cancel", ts=21.125, status="cancelled"),
    ]
    for event in events:
        store.append_event("fresh-session", event)
    runtime = SimpleNamespace(store=store, session_id="fresh-session", restored_history=())
    before = _snapshot(tmp_path)
    records = _history_replay_records(runtime, {"since": since, "limit": limit})
    assert _snapshot(tmp_path) == before
    wire_events = [record for record in records if record["type"] == "runtime.event"]
    effective_since = min(since, len(events))
    expected = events[effective_since:]
    if limit:
        expected = expected[:limit]
    assert len(wire_events) == len(expected)
    decoded = [validate_data_record(record) for record in wire_events]
    assert all(isinstance(record, ReplayedRuntimeEvent) for record in decoded)
    assert [record.sequence for record in decoded] == list(
        range(effective_since + 1, effective_since + len(expected) + 1)
    )
    for record, event in zip(decoded, expected, strict=True):
        assert record.replay is True
        assert record.timestamp == event.ts
        assert record.event.model_dump(mode="json") == event.model_dump(mode="json")
    assert records[-1]["cursor"] == effective_since + len(expected)
    for record in records:
        if record["type"] != "runtime.event":
            with pytest.raises(ValueError):
                validate_data_record(record)


@pytest.mark.parametrize(
    ("field", "bad_value"),
    [
        ("replay", False),
        ("replay", 1),
        ("sequence", 0),
        ("sequence", True),
        ("timestamp", True),
        ("timestamp", []),
        ("schema_version", True),
    ],
)
def test_replay_does_not_broaden_invalid_envelopes(field: str, bad_value: object) -> None:
    event = ContentBlockEnd(event_id="fresh-invalid", ts=30.25, block={"text": "unchanged"})
    record = {
        "schema_version": 1,
        "type": "runtime.event",
        "replay": True,
        "sequence": 1,
        "timestamp": event.ts,
        "event": event.model_dump(mode="json"),
    }
    record[field] = bad_value
    with pytest.raises(ValueError):
        validate_data_record(record)


def test_original_one_shot_shape_remains_distinct() -> None:
    event = ContentBlockEnd(event_id="fresh-live", ts=40.0, block={"text": "live"})
    original = JsonlRecords().runtime_event(event).model_dump(mode="json")
    assert isinstance(original["timestamp"], str)
    assert "replay" not in original
    assert validate_data_record(original).model_dump(mode="json") == original
